-- Spoken-only RP for gestures and reactions. No *emote* output.
local _, addon = ...
local texts = addon.localeData.frFR.generalTexts
texts.RAISE = { gruppe = { "J'aurais encore une question.", "Puis-je ajouter quelque chose ?" }, ziel = { "%s: Puis-je ajouter quelque chose ?", "%s: J'aurais encore une question." } }
texts.RASP = { gruppe = { "C'était ma réponse la plus aimable.", "Ma politesse connaît des limites." }, ziel = { "%s: Ma politesse connaît des limites.", "%s: C'était ma réponse la plus aimable." } }
texts.READY = { gruppe = { "Tout est prêt. J'attends ton signal.", "L'équipement est prêt et la décision est prise." }, ziel = { "%s: L'équipement est prêt et la décision est prise.", "%s: Tout est prêt. J'attends ton signal." } }
texts.REAR = { gruppe = { "On dirait que le cheval veut faire un discours.", "Du calme, mon ami. La route ne va pas s'enfuir." }, ziel = { "%s: Du calme, mon ami. La route ne va pas s'enfuir.", "%s: On dirait que le cheval veut faire un discours." } }
texts.ROAR = { gruppe = { "Même le dernier ennemi peut m'entendre !", "Certains défis méritent un rugissement." }, ziel = { "%s: Certains défis méritent un rugissement.", "%s: Même le dernier ennemi peut m'entendre !" } }
texts.RUDE = { gruppe = { "Aurais-tu égaré tes bonnes manières ?", "Je n'apprécie guère ce comportement." }, ziel = { "%s: Je n'apprécie guère ce comportement.", "%s: Aurais-tu égaré tes bonnes manières ?" } }
texts.SCRATCH = { gruppe = { "Toute cette poussière me donne des démangeaisons.", "Une armure ne protège pas de tous les petits ennemis." }, ziel = { "%s: Une armure ne protège pas de tous les petits ennemis.", "%s: Toute cette poussière me donne des démangeaisons." } }
texts.SEXY = { gruppe = { "Un peu d'assurance ne fait de mal à personne.", "Aujourd'hui je vais montrer mon meilleur côté." }, ziel = { "%s: Aujourd'hui je vais montrer mon meilleur côté.", "%s: Un peu d'assurance ne fait de mal à personne." } }
texts.SHAKE = { gruppe = { "Non, cela ne nous mènera nulle part.", "Nous ne sommes pas obligés d'approuver toutes les absurdités." }, ziel = { "%s: Nous ne sommes pas obligés d'approuver toutes les absurdités.", "%s: Non, cela ne nous mènera nulle part." } }
texts.SHIMMY = { gruppe = { "On peut entendre la musique même sans orchestre.", "Mes épaules ont trouvé le rythme." }, ziel = { "%s: Mes épaules ont trouvé le rythme.", "%s: On peut entendre la musique même sans orchestre." } }
texts.SHIVER = { gruppe = { "Un frisson vient de me parcourir le dos.", "Je doute que ce soit seulement la météo." }, ziel = { "%s: Je doute que ce soit seulement la météo.", "%s: Un frisson vient de me parcourir le dos." } }
texts.SHOO = { gruppe = { "Ouste ! Il n'y a rien à prendre ici !", "Nous aurions besoin d'un peu de tranquillité." }, ziel = { "%s: Nous aurions besoin d'un peu de tranquillité.", "%s: Ouste ! Il n'y a rien à prendre ici !" } }
texts.SHY = { gruppe = { "Je n'ai pas l'habitude d'autant d'attention.", "Nous pourrions commencer par un sujet plus simple." }, ziel = { "%s: Nous pourrions commencer par un sujet plus simple.", "%s: Je n'ai pas l'habitude d'autant d'attention." } }
texts.SIGH = { gruppe = { "Certains jours exigent plus de patience que d'autres.", "Très bien. Recommençons." }, ziel = { "%s: Très bien. Recommençons.", "%s: Certains jours exigent plus de patience que d'autres." } }
texts.SLAP = { gruppe = { "Cela devrait ramener ton attention.", "Un rappel un peu appuyé." }, ziel = { "%s: Un rappel un peu appuyé.", "%s: Cela devrait ramener ton attention." } }
texts.SMELL = { gruppe = { "Quelque chose de très bon mijote non loin.", "Ou serait-ce de la fumée ? Ce serait moins agréable." }, ziel = { "%s: Ou serait-ce de la fumée ? Ce serait moins agréable.", "%s: Quelque chose de très bon mijote non loin." } }
texts.SMIRK = { gruppe = { "Je sais quelque chose que tu ignores encore.", "Un petit secret rend la journée plus intéressante." }, ziel = { "%s: Un petit secret rend la journée plus intéressante.", "%s: Je sais quelque chose que tu ignores encore." } }
texts.SNARL = { gruppe = { "Le prochain pas pourrait être une erreur.", "Il y a des limites qu'il vaut mieux respecter." }, ziel = { "%s: Il y a des limites qu'il vaut mieux respecter.", "%s: Le prochain pas pourrait être une erreur." } }
texts.SNICKER = { gruppe = { "Je suis sûr que ce n'était pas prévu.", "J'essaie vraiment de ne pas rire." }, ziel = { "%s: J'essaie vraiment de ne pas rire.", "%s: Je suis sûr que ce n'était pas prévu." } }
texts.SNIFF = { gruppe = { "Cela sent le début d'une histoire.", "Mon nez hésite encore." }, ziel = { "%s: Mon nez hésite encore.", "%s: Cela sent le début d'une histoire." } }
texts.SNUB = { gruppe = { "Aujourd'hui je n'ai aucune envie de cette conversation.", "Toutes les invitations ne méritent pas de réponse." }, ziel = { "%s: Toutes les invitations ne méritent pas de réponse.", "%s: Aujourd'hui je n'ai aucune envie de cette conversation." } }
texts.SOOTHE = { gruppe = { "Du calme. Le danger est passé.", "Ensemble nous retrouverons notre équilibre." }, ziel = { "%s: Ensemble nous retrouverons notre équilibre.", "%s: Du calme. Le danger est passé." } }
texts.SPIT = { gruppe = { "Ce goût-là ne me manquera pas.", "Certaines choses ne devraient jamais entrer en bouche." }, ziel = { "%s: Certaines choses ne devraient jamais entrer en bouche.", "%s: Ce goût-là ne me manquera pas." } }
texts.SPOON = { gruppe = { "Un endroit chaleureux est un bon début.", "La proximité rend une soirée froide plus douce." }, ziel = { "%s: La proximité rend une soirée froide plus douce.", "%s: Un endroit chaleureux est un bon début." } }
texts.STARE = { gruppe = { "Cela mérite un regard très long.", "J'attends l'explication raisonnable." }, ziel = { "%s: J'attends l'explication raisonnable.", "%s: Cela mérite un regard très long." } }
texts.STINK = { gruppe = { "Il faut absolument ouvrir une fenêtre.", "Ce qui traîne là n'est plus très frais." }, ziel = { "%s: Ce qui traîne là n'est plus très frais.", "%s: Il faut absolument ouvrir une fenêtre." } }
texts.STRONG = { gruppe = { "Ensemble nous résistons mieux que seuls.", "La force consiste aussi à aider les autres." }, ziel = { "%s: La force consiste aussi à aider les autres.", "%s: Ensemble nous résistons mieux que seuls." } }
texts.STRUT = { gruppe = { "Il faut parfois savoir se célébrer.", "Le prochain pas mérite une allure triomphale." }, ziel = { "%s: Le prochain pas mérite une allure triomphale.", "%s: Il faut parfois savoir se célébrer." } }
texts.SURRENDER = { gruppe = { "Je dépose les armes. Pour l'instant.", "Un autre combat ne servirait à personne." }, ziel = { "%s: Un autre combat ne servirait à personne.", "%s: Je dépose les armes. Pour l'instant." } }
texts.SURPRISED = { gruppe = { "Ce n'était pas dans nos projets.", "On n'a donc jamais fini d'apprendre." }, ziel = { "%s: On n'a donc jamais fini d'apprendre.", "%s: Ce n'était pas dans nos projets." } }
texts.TALK = { gruppe = { "Une bonne conversation vaut un détour.", "Parlons avant de décider." }, ziel = { "%s: Parlons avant de décider.", "%s: Une bonne conversation vaut un détour." } }
texts.TALKEX = { gruppe = { "Je pense absolument tout ce que je dis !", "Parfois une pensée doit être dite à haute voix." }, ziel = { "%s: Parfois une pensée doit être dite à haute voix.", "%s: Je pense absolument tout ce que je dis !" } }
texts.TALKQ = { gruppe = { "Peux-tu m'expliquer cela une nouvelle fois ?", "Je veux vraiment comprendre ce que tu veux dire." }, ziel = { "%s: Je veux vraiment comprendre ce que tu veux dire.", "%s: Peux-tu m'expliquer cela une nouvelle fois ?" } }
texts.TAP = { gruppe = { "Ma patience a trouvé un rythme bien audible.", "Qui a dit qu'attendre était facile ?" }, ziel = { "%s: Qui a dit qu'attendre était facile ?", "%s: Ma patience a trouvé un rythme bien audible." } }
texts.TAUNT = { gruppe = { "Approche donc si tu oses !", "Je n'en ai pas fini avec toi." }, ziel = { "%s: Je n'en ai pas fini avec toi.", "%s: Approche donc si tu oses !" } }
texts.TEASE = { gruppe = { "Ce n'était qu'une petite plaisanterie à tes dépens.", "Quelques taquineries maintiennent les amis éveillés." }, ziel = { "%s: Quelques taquineries maintiennent les amis éveillés.", "%s: Ce n'était qu'une petite plaisanterie à tes dépens." } }
texts.THIRSTY = { gruppe = { "Une boisson fraîche serait une bénédiction.", "Ma gorge ressemble à un désert." }, ziel = { "%s: Ma gorge ressemble à un désert.", "%s: Une boisson fraîche serait une bénédiction." } }
texts.THREAT = { gruppe = { "Je ne te préviendrai qu'une fois.", "Ne mets pas ma patience à l'épreuve." }, ziel = { "%s: Ne mets pas ma patience à l'épreuve.", "%s: Je ne te préviendrai qu'une fois." } }
texts.THREATEN = { gruppe = { "Ton prochain pas risque de te coûter cher.", "Cet avertissement n'était pas une plaisanterie." }, ziel = { "%s: Cet avertissement n'était pas une plaisanterie.", "%s: Ton prochain pas risque de te coûter cher." } }
texts.TICKLE = { gruppe = { "Même les héros les plus sérieux ont leurs faiblesses.", "Quelques éclats de rire font des miracles." }, ziel = { "%s: Quelques éclats de rire font des miracles.", "%s: Même les héros les plus sérieux ont leurs faiblesses." } }
texts.TIRED = { gruppe = { "Mes bottes semblent deux fois plus lourdes aujourd'hui.", "J'ai besoin d'un banc, pas d'une nouvelle mission." }, ziel = { "%s: J'ai besoin d'un banc, pas d'une nouvelle mission.", "%s: Mes bottes semblent deux fois plus lourdes aujourd'hui." } }
texts.TRAIN = { gruppe = { "Tchou tchou ! Écartez-vous, le train arrive !", "Qui a dit que les héros devaient toujours être sérieux ?" }, ziel = { "%s: Qui a dit que les héros devaient toujours être sérieux ?", "%s: Tchou tchou ! Écartez-vous, le train arrive !" } }
texts.VETO = { gruppe = { "Je m'oppose fermement à ce projet.", "Un projet ne s'améliore pas parce qu'on crie." }, ziel = { "%s: Un projet ne s'améliore pas parce qu'on crie.", "%s: Je m'oppose fermement à ce projet." } }
texts.VIOLIN = { gruppe = { "Hélas, quel destin tragique.", "Dois-je jouer une mélodie particulièrement triste ?" }, ziel = { "%s: Dois-je jouer une mélodie particulièrement triste ?", "%s: Hélas, quel destin tragique." } }
